import { UserLoginView } from "./components/UserLoginView";
import { GoogleSheetsManager } from "./components/GoogleSheetsManager";
import { OfflineSyncModal } from "./components/OfflineSyncModal";
import { PWAInstallBanner } from "./components/PWAInstallBanner";
import { GvizSyncErrorBanner } from "./components/GvizSyncErrorBanner";
import {
  isAppOnline,
  getPendingQueueCount,
  addToOfflineQueue,
  syncAllPendingQueue
} from "./lib/offlineSyncService";
import {
  getAllPatients,
  getActiveUserProfile,
  saveActiveUserProfile,
  syncPatientFromFormSubmission,
  upsertPatient,
  deletePatientById,
  PREDEFINED_USER_PROFILES,
  logoutPetugas,
  recordUserActivity,
  getLastUserActivityTimestamp,
  INACTIVITY_TIMEOUT_MS,
  isSessionExpired,
  pullAllCloudData
} from "./lib/patientMonitoring";
import {
  computeAppNotifications,
  AppNotification
} from "./lib/notificationService";
import { OFFICIAL_SIGNATURE_STAMP_URL, DEFAULT_PELAKSANA_NAMA, DEFAULT_PELAKSANA_NIP, getOfficialSignatureUrl } from "./components/SignatureData";
