      tanggalKejadian: formData.tanggalKejadian || formData.waktuKejadian || "",
      jamKejadian: formData.jamKejadian || "",
      alamatKejadian: formData.alamatKejadian || "",
      tanggalPelaksanaan: formData.tanggalPelaksanaan || "",
